insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('47277403-1eee-4cc5-83e3-b041c7c70b85', '1f848433-ff7b-418d-8ca4-9b7740a3a263', $$bron 1: afbeelding van stemmende burgers met Athena op een Atheense schaal (ca. 475 v.Chr.)$$,
   $$geschiedenis-vwo-2025-ii-prehistorie-en-oudheid-bron1.png$$,
   $$bron 1 Een afbeelding op een aardewerken schaal, omstreeks 475 voor Christus gemaakt in de stadstaat Athene:
[Afbeelding] Rode figuren op een aardewerken schaal: in het midden een vrouwenfiguur met helm (Athena) bij een verhoging; links en rechts staan mannen die hun stem uitbrengen.
Toelichting: In het midden van de afbeelding staat Athena, Griekse godin van de wijsheid en beschermgodin van de stadstaat Athene. Links en rechts staan Atheense burgers die stemmen.$$, 'inline'),
  ('cbea9bab-bdf4-434b-aadb-5c629ee774ae', '2493cd4a-500d-4301-b544-9b1221503de1', $$bron 2: voorwoord van Boccaccio bij Over beroemde vrouwen (ca. 1362)$$,
   $$geschiedenis-vwo-2025-ii-de-middeleeuwen-bron2.png$$,
   $$bron 2 Omstreeks 1362 schrijft de Italiaanse auteur Giovanni Boccaccio het boek Over beroemde vrouwen, met daarin biografieën van Bijbelse, mythologische en historische vrouwen. In het voorwoord staat:
In navolging van hun heilige Leraar [God] dwongen Hebreeuwse en christelijke vrouwen zichzelf meestal tot een bovenmenselijke volharding met het doel eeuwigdurende en ware glorie te behalen. Heidense vrouwen1) echter bereikten hun doel (…) door hun talent of, waarschijnlijker, omdat ze werden aangespoord door een verlangen naar aardse roem. Daarnaast verkregen christelijke vrouwen, in het ware en altijd schijnende licht, hun verdiende onsterfelijkheid. Ook weten we dat hun maagdelijkheid, zuiverheid, heiligheid en hun standvastigheid in het overwinnen van vleselijke lusten (…), in boeken van vrome mannen zijn beschreven. Er zijn echter nog geen boeken waarin speciaal over de verdiensten van de heidense vrouwen wordt geschreven. Om die reden (…) heb ik dit boek geschreven.
noot 1 Boccaccio bedoelt hiermee vrouwen uit de Grieks-Romeinse mythologie en geschiedenis.$$, 'inline'),
  ('6a94300c-f9de-47e6-b2fb-675fbe1e7b6a', '07427ad0-f817-4c62-842d-58d87c7ae035', $$bron 3: een Fransman over koopman Bijland en Frederik Hendrik (1638)$$,
   $$geschiedenis-vwo-2025-ii-steden-en-burgers-1050-1700-bron3.png$$,
   $$bron 3 Stadhouder Frederik Hendrik, prins van Oranje, verzoekt in 1638 aan het Amsterdamse stadsbestuur koopman Bijland te arresteren die buskruit en wapens levert aan Antwerpen. Een Fransman schrijft hierover:
Hij [koopman Bijland] had geantwoord dat de burgers van Amsterdam vrijheid hadden om overal te handelen; dat hij er honderd kon noemen die aan de Antwerpenaren leverden, dat hij het ook deed, dat de koophandel niet geremd kon worden. En dat hij hun wel betuigen wilde dat men om winst te maken door "de hel varen moest". (…) De heren van Amsterdam hadden hem toen onschuldig verklaard omdat hij maar een leverancier was en alleen gehandeld had in opdracht van Antwerpse kooplieden. Mijnheer de Prins van Oranje was zeer ontstemd over dit verhaal. Hij stuurde gelijk iemand naar Admiraal Tromp met de opdracht om de vier fluiten1) met buskruit en geweren in Texel aan te houden. (…) "Gij ziet", zei hij mij toen, "hoeveel geduld men hebben moet met deze plompaarts2) van kooplieden. Ik heb geen grotere vijanden dan de stad Amsterdam."
noot 1 Een fluit is een scheepstype. noot 2 Dit betekent lomp en onbehouwen.$$, 'inline'),
  ('2024d03e-cfd6-4c57-a208-63650947dbf9', 'e01e57ab-2b5d-45c4-b6cc-cfe13b29196e', $$bron 5: brief van Leopold van Oostenrijk aan zijn zus (1790)$$,
   $$geschiedenis-vwo-2025-ii-verlichting-1650-1900-bron5.png$$,
   $$bron 5 Op 15 januari 1790 schrijft troonopvolger Leopold van Oostenrijk aan zijn zus:
De heerser, zelfs een erfelijke, is alleen maar een ambtenaar van het volk, die alle aandacht moet geven aan het bevorderen van de welvaart van dat volk. In ieder land moet een grondwet tussen het volk en de soeverein
overeengekomen worden, die de macht en de bevoegdheden van de
soeverein begrenst. Als de vorst dit verdrag verbreekt, dan doet hij afstand van zijn positie en is niemand nog verplicht om hem te gehoorzamen. Alleen de uitvoerende macht ligt bij de heerser; de wetgevende bij het volk en zijn vertegenwoordigers.$$, 'inline'),
  ('5cefe6e7-364f-4f84-a945-b004c28f313f', 'e01e57ab-2b5d-45c4-b6cc-cfe13b29196e', $$bron 6: plakkaat van het bestuur van Holland over het verbod op livreien (1795)$$,
   $$geschiedenis-vwo-2025-ii-verlichting-1650-1900-bron6.png$$,
   $$bron 6 In 1795 staat in een plakkaat van het bestuur van het gewest Holland:
Dat uiterlijk voor 1 september 1795 men zal moeten ophouden met het dragen van livreien1), dat iedereen die na die tijd nog wordt aangetroffen met deze
kleding meteen zal worden gearresteerd en naar de gevangenis wordt
gebracht en dat daar die kleding zal worden uitgetrokken en dat als deze persoon nogmaals in deze kleding wordt aangetroffen zonder vorm van
proces zal worden veroordeeld om (…) in zijn livrei op een schavot te kijk te worden gezet en daarna uit het rechtsgebied verbannen te worden. En aan degene bij wie de livreidragende persoon in huis wordt aangetroffen of in
dienst was, wordt bij de eerste keer een boete van 100 en bij een tweede keer een boete van 1000 gouden dukaten gegeven.
noot 1 Een livrei is een uniform van een bediende, in de kleuren van de familie waar de bediende voor werkt.$$, 'inline'),
  ('31b87f06-e96e-498e-8a11-bbf55e184bde', 'c3aaa3f0-c76f-4c72-b0ee-e2905c240b1e', $$bron 2: voorwoord van Boccaccio bij Over beroemde vrouwen (ca. 1362)$$,
   $$geschiedenis-vwo-2025-ii-vroegmoderne-tijd-bron2.png$$,
   $$bron 2 Omstreeks 1362 schrijft de Italiaanse auteur Giovanni Boccaccio het boek Over beroemde vrouwen, met daarin biografieën van Bijbelse, mythologische en historische vrouwen. In het voorwoord staat:
In navolging van hun heilige Leraar [God] dwongen Hebreeuwse en christelijke vrouwen zichzelf meestal tot een bovenmenselijke volharding met het doel eeuwigdurende en ware glorie te behalen. Heidense vrouwen1) echter bereikten hun doel (…) door hun talent of, waarschijnlijker, omdat ze werden aangespoord door een verlangen naar aardse roem. Daarnaast verkregen christelijke vrouwen, in het ware en altijd schijnende licht, hun verdiende onsterfelijkheid. Ook weten we dat hun maagdelijkheid, zuiverheid, heiligheid en hun standvastigheid in het overwinnen van vleselijke lusten (…), in boeken van vrome mannen zijn beschreven. Er zijn echter nog geen boeken waarin speciaal over de verdiensten van de heidense vrouwen wordt geschreven. Om die reden (…) heb ik dit boek geschreven.
noot 1 Boccaccio bedoelt hiermee vrouwen uit de Grieks-Romeinse mythologie en geschiedenis.$$, 'inline'),
  ('1b3d6682-04d5-40fd-9c6f-a1b93223428b', 'c3aaa3f0-c76f-4c72-b0ee-e2905c240b1e', $$bron 4: familieportret van koopman Jeremias van Collen door Pieter van Anraedt (ca. 1655)$$,
   $$geschiedenis-vwo-2025-ii-vroegmoderne-tijd-bron4.png$$,
   $$bron 4 Omstreeks 1655 schildert Pieter van Anraedt dit familieportret van de Amsterdamse koopman Jeremias van Collen en zijn gezin:
[Afbeelding] Schilderij van een man en een vrouw met hun twaalf kinderen op een terras met een balustrade en een zuil; links op de achtergrond een landhuis met tuin, vooraan een hondje.
Toelichting: Het schilderij toont Jeremias van Collen, zijn vrouw en hun twaalf kinderen. Op de achtergrond staat hun landhuis Velserbeek. Het terras waarop de familie is afgebeeld, bestaat in werkelijkheid niet.$$, 'inline'),
  ('bfe2a46c-b540-4eed-bc8b-6e34f6311891', '46480c9e-c3c4-45f0-aa14-33f6cbfab8f8', $$bron 7: schilderij van William Daniell van Europese handelsposten in Kanton (1806)$$,
   $$geschiedenis-vwo-2025-ii-china-1842-2001-bron7.png$$,
   $$bron 7 In 1806 maakt William Daniell dit schilderij van Europese handelsposten in Kanton:
[Afbeelding] Schilderij van een rivieroever met links Chinese jonken en kleine boten; op de achtergrond een rij Europese handelsgebouwen met hoge vlaggenmasten waaraan nationale vlaggen wapperen.
Toelichting: Vanaf de achttiende eeuw staat de Chinese overheid buitenlandse naties alleen toe om vanuit een eigen handelspost in Kanton (vlak bij Hongkong) handel te drijven met China. Voor de handelsposten zijn de vlaggen te zien van Denemarken, Frankrijk, Zweden, Groot-Brittannië en Koninkrijk Holland.$$, 'inline'),
  ('61a261dc-9c55-46bd-b22e-c37db713b786', '46480c9e-c3c4-45f0-aa14-33f6cbfab8f8', $$bron 13: dagboek van Mao's lijfarts dr. Li Zhizui over een gesprek met Mao (jaren 1960)$$,
   $$geschiedenis-vwo-2025-ii-china-1842-2001-bron13.png$$,
   $$bron 13 Dr. Li Zhizui is tussen 1954 en 1976 de lijfarts van Mao. Hij schrijft in zijn dagboek over een gesprek met Mao in de jaren 1960:
"Tijdens de burgeroorlog tussen nationalisten en communisten bood Stalin geen hulp, en weigerde aan de communistische strijdkrachten zelfs maar een geweer of kogel te geven, zelfs geen scheet", zei Mao. (…) "Tijdens de Koreaanse oorlog1), toen het Amerikaanse leger de grens tussen China en Korea bereikte bij de Yalu-rivier, zei ik Stalin dat we onze troepen ernaartoe moesten sturen om te vechten," zei Mao. "Maar Stalin zei nee. Hij dacht dat dat het begin van een derde wereldoorlog zou zijn."
noot 1 In Korea vechten tussen 1950 en 1953 Noord-Koreaanse communistische troepen tegen troepen van Zuid-Korea en van de Verenigde Naties.$$, 'inline'),
  ('ed985eed-cf5f-41c8-a3ab-e8f581e537a3', '6e924cc7-bbc7-4bfc-bb0d-fc74ba6e7e9b', $$bron 8: oproep van de Algemeene Vereeniging tegen het Pauperisme in de Groninger Courant (1852)$$,
   $$geschiedenis-vwo-2025-ii-moderne-tijd-bron8.png$$,
   $$bron 8 In 1851 wordt in Groningen door een groep heren uit de hogere burgerij de Algemeene Vereeniging tegen het Pauperisme1) opgericht. Het bestuur publiceert in 1852 in de Groninger Courant een oproep:
Dat het voordelig zou werken wanneer alle werkbazen, kooplieden en allen die wekelijks loon uitbetalen besloten die uitbetaling niet meer op zaterdag, maar op een andere werkdag te doen. En ook om onder het werk geen borrel meer te schenken maar het bedrag daarvan ten voordeel van hun werklieden in de Spaarkas te beleggen. Zo zal de werkman de verleiding worden ontnomen die hij krijgt door het ontvangen van zijn werkloon op zaterdag om een ruim deel daarvan aan jenever te besteden, waardoor wanorde en zedeloosheid, twist en tweedracht in huisgezinnen wordt veroorzaakt.
noot 1 Pauperisme is een term voor armoede.$$, 'inline'),
  ('9084e2f1-f1a4-4c3c-bbb1-0fc5f6d3d5c5', '6e924cc7-bbc7-4bfc-bb0d-fc74ba6e7e9b', $$bron 9: foto van een demonstratie van vrouwen in Boston (1935)$$,
   $$geschiedenis-vwo-2025-ii-moderne-tijd-bron9.png$$,
   $$bron 9 Foto van een demonstratie in de Amerikaanse stad Boston in 1935:
[Afbeelding] Zwart-witfoto van een groep vrouwen met protestborden, met teksten als ''FIRE MARRIED WOMEN Hire Needy Single Women'', ''THOUSANDS of SINGLE WOMEN NEED JOBS'' en ''IF MARRIED WOULD WE GET JOBS''.
Toelichting: Op de borden staan leuzen als ''Duizenden alleenstaande vrouwen hebben een baan nodig'', ''Ontsla gehuwde vrouwen – neem alleenstaande vrouwen aan die het nodig hebben'', ''Zouden we een baan krijgen als we gehuwd waren!'', ''Duizenden gehuwde vrouwen bij de E.R.A. (door de overheid gesubsidieerde banen)''.$$, 'inline'),
  ('5d2f905d-c20e-48ff-b567-46fda9033f57', 'c7f7e673-274c-4cc6-9e2c-cab3430e6718', $$bron 10: rapport van NSB-districtsleider Stoetzer aan Mussert (1943)$$,
   $$geschiedenis-vwo-2025-ii-duitsland-in-europa-1918-1991-bron10.png$$,
   $$bron 10 In 1943 breken in Nederland stakingen uit tegen de Duitse bezetter. A. Stoetzer, de districtsleider van de Nationaal Socialistische Beweging (NSB) in Noord-Brabant, schrijft in een rapport aan Mussert, de landelijke leider van de NSB:
De stemming van het volk na het gebeurde is moeilijk te bepalen. (…) Op sommige plaatsen is de stemming zelfs meer anti-Engels geworden, omdat de bevolking in het naïeve vertrouwen geleefd had, dat men van de overkant hulp zou krijgen. Wel is men in het algemeen verontwaardigd over het feit dat van de Philipsfabrieken te Eindhoven alleen vier gewone arbeiders en een gewone kantoorbediende doodgeschoten zijn1). (…) Hoewel de stemming door een en ander niet meer anti-NSB geworden is dan die reeds was, zal de propaganda toch veel moeilijker worden. Nodig schijnt mij in ieder geval, dat vele min of meer hooggeplaatste personen, die zich bij deze gebeurtenissen bloot gegeven hebben, alsnog aangepakt worden. (…) Ook bij de politie dient nog veel verbeterd te worden. De vervanging van enkele burgemeesters moet noodzakelijk volgen.
noot 1 De Duitse bezetter schiet als strafmaatregel enkele Nederlandse stakers dood.$$, 'inline'),
  ('3150307d-56ac-4748-8003-e811ae23e53b', 'c7f7e673-274c-4cc6-9e2c-cab3430e6718', $$bron 11: pamflet van Ulbricht aan Duitse soldaten (1942), gepubliceerd in 1953$$,
   $$geschiedenis-vwo-2025-ii-duitsland-in-europa-1918-1991-bron11.png$$,
   $$bron 11 Ulbricht brengt in 1953 zijn boek Zur Geschichte der deutschen Arbeiterbewegung II 1933-1946 uit. Hierin staat dat Ulbricht in december 1942 een pamflet schrijft aan de Duitse soldaten in de Sovjet-Unie:
Soldaten, landgenoten! (…) De leiding van het Rode Leger1) verzekert u: iedereen die zich overgeeft, wordt niet langer als een vijand beschouwd. De Russische arbeiders en boeren weten dat niet jullie, maar de Duitse bewapenende miljonairs de echte boosdoeners zijn in de oorlog. Ze denken er niet aan om wraak op je te nemen. Terwijl ik deze woorden schrijf, zitten wij hier met Duitse krijgsgevangenen die zeggen dat als jullie daar zouden weten hoe menselijk het hier toegaat, jullie niet meer zouden schieten. Landgenoten! De enige poort naar jullie redding is open. (…) Stel je de vreugde voor van je dierbaren wanneer ze met Kerstmis het goede nieuws ontvangen dat je veilig bent en bij hen terug zult keren als de oorlog voorbij is.
noot 1 Dit is het leger van de Sovjet-Unie.$$, 'inline'),
  ('ac9ac1c2-9c27-400d-bcf8-7ab5413f1679', 'c7f7e673-274c-4cc6-9e2c-cab3430e6718', $$bron 12: Ulbricht in gesprek met Chroesjtsjov (1 augustus 1961)$$,
   $$geschiedenis-vwo-2025-ii-duitsland-in-europa-1918-1991-bron12.png$$,
   $$bron 12 Op 1 augustus 1961 zegt Ulbricht tijdens een gesprek met Chroesjtsjov, de leider van de Sovjet-Unie:
Toen we het plan opzetten, rekenden we op de hulp van de volksdemocratieën. We hebben gereedschap om metaal te bewerken verkocht aan de Tsjechen, en die zouden ons daarvoor volgens het contract 8000 ton staal leveren in 1960. Maar dat hebben ze niet gedaan. De Polen en Bulgaren handelen op dezelfde manier. De Bulgaren staan nu voor 60 miljoen bij ons in het krijt; dat betekent dat we hen nu krediet verstrekken. (…) Er is geen samenwerking tussen de socialistische landen, en de vraag wie nieuwe machines kan maken op basis van westerse ontwerpen zal niet worden opgelost. Zo kochten de Roemenen van de Amerikanen een machine voor het drogen van plastic. Als we vier van dergelijke machines zouden hebben, zouden we de productie van plastic kunnen verdubbelen. Maar de Comecon houdt zich niet bezig met deze kwestie en dupliceert de ontwerpen van dergelijke nieuwe machines niet. (…) Momenteel werkt iedereen alleen voor zichzelf, met als gevolg dat we sterk afhankelijk worden van het Westen. De Comecon moet hier controle over krijgen en samenwerken.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('6f532e62-4960-42d6-954b-57d2aa2dad24', '3a71376f-9e42-41b5-8e9c-8f8fae3927b7', 1,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Grieken en Romeinen (3000 v.Chr.-500 n.Chr.)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Monniken en ridders (500-1000)"}, {"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij en centralisatie (1302-1602)"}]'::jsonb,
   '["chronologie", "Atheense democratie", "kloosters", "Opstand", "Gouden Eeuw", "landbouwsamenleving"]'::jsonb,
   $$Chronologisch ordenen van zes gegevens over strijdbare vrouwen uit verschillende tijdvakken.$$,
   $$geschiedenis-vwo-2025-ii-door-de-tijd-heen-vraag1.png$$, $$De volgende gegevens over strijdbare vrouwen staan in willekeurige volgorde:
1 Aspasia, de minnares van de Atheense politicus Perikles, was volgens de komedieschrijver Aristofanes schuldig aan het uitbreken van een oorlog tussen de steden Athene en Sparta.
2 De inheems-Amerikaanse leider Lozen vluchtte voor het leger van de Verenigde Staten van Amerika, nadat ze met haar volk uit het reservaat vertrok dat aan hen was toegewezen.
3 Koningin Kubaba herenigde volgens legendes Soemerië, een van de weinige landen waar op dat moment al graan werd verbouwd.
4 Onder leiding van Trijn van Leemput vernietigde een groep Utrechters de dwangburcht Vredenburg nadat de troepen van Filips II de stad hadden verlaten.
5 Radegundis, de koningin van de Franken, had zo''n hekel aan haar man dat ze een van de eerste kloosters in Frankrijk stichtte om zich daarin te kunnen terugtrekken.
6 Tijdens de Gouden Eeuw dienden zestig Hollandse soldaten in het leger van de Angolese koningin Nzinga, die jonge soldaten met een krijgsdans voorbereidde op gevechten. 2p 1 Zet deze gegevens in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('dc952bee-7927-43f2-bde7-8ed039b81f2b', '3a71376f-9e42-41b5-8e9c-8f8fae3927b7', 12,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij en centralisatie (1302-1602)"}, {"domain": "Steden en burgers in de Lage Landen", "subdomain": "Opkomst van de stedelijke burgerij (1050-1302)"}, {"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij in de Gouden Eeuw (1602-1700)"}]'::jsonb,
   '["chronologie", "Guldensporenslag", "Karel V", "Opstand", "Johan de Witt", "Romantiek"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen waarbij broers een rol speelden, van de Guldensporenslag tot de Romantiek.$$,
   $$geschiedenis-vwo-2025-ii-door-de-tijd-heen-vraag12.png$$, $$De volgende gebeurtenissen, waarbij broers een rol hebben gespeeld, staan in willekeurige volgorde:
1 De vijf gebroeders Butler vochten allen onder leiding van George Washington.
2 Door het verzamelen publiceren van sprookjes en volksverhalen droegen Jacob en Wilhelm Grimm bij aan de verspreiding van de Romantiek in Duitsland.
3 Gwijde en Rudolf de Nesle sneuvelden tijdens de Guldensporenslag nadat ze van hun paarden waren getrokken.
4 Johan en Cornelis de Witt werden vermoord omdat zij vonden dat er geen stadhouder mocht worden gekozen.
5 Lodewijk en Hendrik van Nassau, broers van Willem van Oranje, sneuvelden tijdens de Slag op de Mookerheide tegen het Spaanse leger.
6 Simon en Adriaan Borluut kwamen samen met andere Gentse patriciërs in opstand tegen de belastingpolitiek van Karel V. 2p 12 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('3a9398dd-61bf-4106-bf07-293df8fb33a0', '1f848433-ff7b-418d-8ca4-9b7740a3a263', 2,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Grieken en Romeinen (3000 v.Chr.-500 n.Chr.)"}]'::jsonb,
   '["Atheense democratie", "burgerschap", "Griekse stadstaat", "Athena", "stemmen", "boodschap van de maker"]'::jsonb,
   $$Uitleggen welke boodschap over de Atheense democratie een afbeelding van stemmende burgers met de godin Athena overbrengt.$$,
   $$geschiedenis-vwo-2025-ii-prehistorie-en-oudheid-vraag2.png$$, $$Gebruik bron 1. Met deze afbeelding wordt een boodschap overgebracht over de democratie in Athene. 2p 2 Leg uit welke boodschap deze afbeelding overbrengt.$$, array['47277403-1eee-4cc5-83e3-b041c7c70b85']::uuid[]),
  ('a913349b-3877-4228-aa9e-83340caa42fd', '1f848433-ff7b-418d-8ca4-9b7740a3a263', 3,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Grieken en Romeinen (3000 v.Chr.-500 n.Chr.)"}]'::jsonb,
   '["Romeinse rijk", "Germaanse cultuur", "grensgebied", "Caesar", "Helvetiërs", "kenmerkend aspect"]'::jsonb,
   $$Met een kenmerkend aspect het Romeinse belang uitleggen bij Caesars besluit de Helvetiërs terug te sturen en een verdrag te sluiten.$$,
   $$geschiedenis-vwo-2025-ii-prehistorie-en-oudheid-vraag3.png$$, $$In de eerste eeuw voor Christus verlieten de Helvetiërs hun woongebied in het Romeinse Rijk, vlakbij de noordelijke grens. Ze trokken verder het Romeinse Rijk in. De Romeinse generaal Caesar nam het besluit de Helvetiërs te laten terugkeren naar hun oorspronkelijke woongebied en een samenwerkingsverdrag met hen te tekenen. 1p 3 Geef met behulp van een kenmerkend aspect aan welk belang de Romeinen hadden bij dit besluit van Caesar. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array[]::uuid[]),
  ('00dc9dd8-c32c-4838-adf5-48464f029015', '2493cd4a-500d-4301-b544-9b1221503de1', 4,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Steden en staten — overig (1000-1500)"}]'::jsonb,
   '["Investituurstrijd", "paus", "wereldlijke en geestelijke macht", "feodaliteit", "continuïteit en verandering", "kenmerkend aspect"]'::jsonb,
   $$Met het citaat van Langton politieke continuïteit tussen vroege en late middeleeuwen aantonen en de weigering van Jan zonder Land verklaren.$$,
   $$geschiedenis-vwo-2025-ii-de-middeleeuwen-vraag4.png$$, $$Een geschiedenis: Paus Innocentius III wijdde in 1207 Stephen Langton tot de nieuwe aartsbisschop van het Engelse Canterbury. De Engelse koning Jan zonder Land accepteerde deze wijding niet. Langton schreef vervolgens aan het Engelse volk: "als een rebellerende landsheer zijn trouw aan God terugtrekt, dan zijn de onderdanen ontslagen van de trouw die ze hem verschuldigd zijn." 3p 4 Licht deze geschiedenis toe door:
− met een verwijzing naar het citaat van Langton aan te tonen dat er sprake was van politieke continuïteit tussen de vroege en late middeleeuwen, en
− met een kenmerkend aspect een verklaring te geven voor de weigering van Jan zonder Land om de wijding van Langton te accepteren. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array[]::uuid[]),
  ('87a14c58-02f4-4dcb-806a-8a652e16f77d', '2493cd4a-500d-4301-b544-9b1221503de1', 5,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Opkomst van de stedelijke burgerij (1050-1302)"}]'::jsonb,
   '["handel", "agrarisch-urbane samenleving", "staatsvorming en centralisatie", "lakennijverheid", "Vlaanderen", "kenmerkend aspect"]'::jsonb,
   $$Met een geschiedenis over Italiaanse kooplieden en belastinginners twee kenmerkende aspecten van de late middeleeuwen aantonen.$$,
   $$geschiedenis-vwo-2025-ii-de-middeleeuwen-vraag5.png$$, $$Een geschiedenis: In 1302 klaagden Italiaanse kooplieden bij de hoogste rechtbank in Parijs over plaatselijke belastinginners die in sommige plattelandsstreken in Frankrijk meer dan de gebruikelijke belasting eisten over het vervoer van laken uit Vlaanderen. Het gerechtshof vonniste dat de belastinginners genoegen moesten nemen met het oude bedrag. Met deze geschiedenis kun je verschillende kenmerkende aspecten uit de late middeleeuwen illustreren. 2p 5 Toon dit aan voor twee kenmerkende aspecten. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array['cbea9bab-bdf4-434b-aadb-5c629ee774ae']::uuid[]),
  ('b2907c29-7e07-46a9-a174-d74eb834471f', '07427ad0-f817-4c62-842d-58d87c7ae035', 7,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij en centralisatie (1302-1602)"}]'::jsonb,
   '["bonum commune", "armenzorg", "stadsbestuur", "Haarlem", "stedelijke burgerij", "continuïteit en verandering"]'::jsonb,
   $$Aantonen dat de Haarlemse broodbedeling van 1475 past bij het bonum commune en bij een verandering in de armenzorg.$$,
   $$geschiedenis-vwo-2025-ii-steden-en-burgers-1050-1700-vraag7.png$$, $$Een geschiedenis: In de Sint-Bavokerk in Haarlem deelden vanaf 1475 burgers, die hiervoor werden aangesteld door het stadsbestuur, wekelijks brood uit aan de armen van de stad. Als dank voor het ontvangen van brood moesten de armen bidden voor het zielenheil van de burgers die deze hulp betaalden. Deze geschiedenis toont aan dat in Haarlem in 1475:
− het stadsbestuur uitging van het idee van bonum commune, en
− een verandering had plaatsgevonden in de armenzorg. 2p 7 Toon aan dat beide beweringen juist zijn, telkens met een verwijzing naar deze geschiedenis.$$, array[]::uuid[]),
  ('74232fe1-d398-4144-b4d4-b1cfe34e3acb', '07427ad0-f817-4c62-842d-58d87c7ae035', 9,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij in de Gouden Eeuw (1602-1700)"}]'::jsonb,
   '["particularisme", "stadhouder", "regenten", "Tachtigjarige Oorlog", "Amsterdam", "Antwerpen"]'::jsonb,
   $$Aantonen dat de wapenhandel van een Amsterdamse koopman botste met de oorlogsfinanciering en het particularisme in de Republiek.$$,
   $$geschiedenis-vwo-2025-ii-steden-en-burgers-1050-1700-vraag9.png$$, $$Gebruik bron 3. Je concludeert dat het conflict in de bron wordt veroorzaakt doordat veel regenten in de Republiek als uitgangspunt hebben dat:
1 ze de strijd tegen Spanje met handel kunnen financieren, en
2 particularisme moet worden nagestreefd. 3p 9 Licht de conclusies toe door:
− met bron voor beide uitgangspunten apart aan te tonen dat de handelswaar van koopman Bijland voor problemen zorgt, en
− zonder bron aan te geven waardoor in Amsterdam veel kooplieden juist met Antwerpen een goede handelsrelatie hebben.$$, array['6a94300c-f9de-47e6-b2fb-675fbe1e7b6a']::uuid[]),
  ('b9549a9d-6db0-4162-af65-695eb9eee4d5', 'e01e57ab-2b5d-45c4-b6cc-cfe13b29196e', 11,
   '[{"domain": "Verlichting", "subdomain": "Verlichte ideeën over een rechtvaardige samenleving (1650-1789)"}]'::jsonb,
   '["Locke", "Montesquieu", "sociaal contract", "scheiding der machten", "verlicht absolutisme", "volkssoevereiniteit"]'::jsonb,
   $$Aantonen dat de uitgangspunten van Leopold van Oostenrijk aansluiten bij ideeën van Locke en Montesquieu.$$,
   $$geschiedenis-vwo-2025-ii-verlichting-1650-1900-vraag11.png$$, $$Gebruik bron 5. De uitgangspunten van Leopold sluiten aan bij politieke ideeën van Locke en Montesquieu. 2p 11 Toon dit apart aan voor een idee van Locke en voor een idee van Montesquieu.$$, array['2024d03e-cfd6-4c57-a208-63650947dbf9']::uuid[]),
  ('831ab157-0bdf-4715-b3c4-1aee59ae0de2', 'e01e57ab-2b5d-45c4-b6cc-cfe13b29196e', 13,
   '[{"domain": "Verlichting", "subdomain": "Democratische revoluties in de VS en Frankrijk (1776-1813)"}]'::jsonb,
   '["Haïtiaanse Revolutie", "slavernij", "Amerikaanse Revolutie", "plantagekoloniën", "slaafgemaakten", "onafhankelijkheid"]'::jsonb,
   $$Verklaren waarom Dessalines steun van de Verenigde Staten verwachtte en waarom de VS om binnenlandse redenen weigerden.$$,
   $$geschiedenis-vwo-2025-ii-verlichting-1650-1900-vraag13.png$$, $$In de Franse kolonie Saint-Domingue (het huidige Haïti) brak in 1791 een opstand uit onder de slaafgemaakten. Na jaren van strijd riep Jean-Jacques Dessalines, een van de leiders van de opstand, in 1804 de onafhankelijkheid uit. Hij besloot de Verenigde Staten te vragen om een bondgenootschap, maar die besloten zijn verzoek af te wijzen. 3p 13 Licht beide besluiten toe door:
− te beredeneren waarom Dessalines verwachtte dat zijn verzoek door de regering van de Verenigde Staten zou worden ingewilligd, en
− een binnenlands politiek argument te noemen dat de reden was voor de Verenigde Staten om het verzoek van Dessalines af te wijzen.$$, array[]::uuid[]),
  ('4febc2d0-7bc0-4c7d-834f-79d3a7a45292', 'e01e57ab-2b5d-45c4-b6cc-cfe13b29196e', 14,
   '[{"domain": "Verlichting", "subdomain": "Democratische revoluties in de VS en Frankrijk (1776-1813)"}]'::jsonb,
   '["Bataafse Revolutie", "gelijkheid", "standensamenleving", "verlicht idee", "plakkaat", "revolutie"]'::jsonb,
   $$Uitleggen welk verlicht idee het Hollandse revolutionaire bestuur met het verbod op livreien in 1795 uitvoerde.$$,
   $$geschiedenis-vwo-2025-ii-verlichting-1650-1900-vraag14.png$$, $$Gebruik bron 6. In 1795 krijgt Holland een nieuw revolutionair bestuur. 2p 14 Leg uit welk verlicht idee tot uitvoer wordt gebracht met dit plakkaat.$$, array['5cefe6e7-364f-4f84-a945-b004c28f313f']::uuid[]),
  ('9cb608a1-382c-4f1e-9d5b-14484508cf1f', 'e01e57ab-2b5d-45c4-b6cc-cfe13b29196e', 15,
   '[{"domain": "Verlichting", "subdomain": "Verlichtingsideeën in de Europese politieke cultuur (1813-1900)"}]'::jsonb,
   '["Congres van Wenen", "restauratie", "conservatisme", "standensamenleving", "1815", "politieke situatie"]'::jsonb,
   $$Aangeven dat het opheffen van het livreiverbod na 1815 paste bij de restauratie in Europa.$$,
   $$geschiedenis-vwo-2025-ii-verlichting-1650-1900-vraag15.png$$, $$Na 1815 werd het verbod op het dragen van een livrei (zie bron 6) weer opgeheven in Nederland. 1p 15 Geef aan dat het opheffen van het verbod op het dragen van een livrei paste bij de politieke situatie in Europa direct na 1815.$$, array['5cefe6e7-364f-4f84-a945-b004c28f313f']::uuid[]),
  ('2f0dd710-15bd-482b-8458-f4288516066f', 'c3aaa3f0-c76f-4c72-b0ee-e2905c240b1e', 6,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["renaissance", "humanisme", "mensbeeld", "klassieke oudheid", "Boccaccio", "bronverwijzing"]'::jsonb,
   $$Aantonen dat Boccaccio's boek over beroemde vrouwen past bij het mensbeeld van de renaissance en de werkwijze van een humanist.$$,
   $$geschiedenis-vwo-2025-ii-vroegmoderne-tijd-vraag6.png$$, $$Gebruik bron 2. Het boek Over beroemde vrouwen past bij de tijd van de renaissance. 2p 6 Licht dit toe door:
− aan te tonen met een verwijzing naar de bron dat het motief van Boccaccio om over ''heidense vrouwen'' te schrijven past bij het veranderende mensbeeld van de renaissance, en
− aan te geven dat de werkwijze van Boccaccio die van een humanist is.$$, array['31b87f06-e96e-498e-8a11-bbf55e184bde']::uuid[]),
  ('7e00364c-6539-4cfd-affd-665435c05147', 'c3aaa3f0-c76f-4c72-b0ee-e2905c240b1e', 8,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["Europese overzeese expansie", "wereldbeeld", "missionaris", "standplaatsgebondenheid", "christendom", "Afrika"]'::jsonb,
   $$Uitleggen dat een Portugese missionaris prehistorische Afrikaanse rotstekeningen bekeek vanuit zijn christelijke wereldbeeld.$$,
   $$geschiedenis-vwo-2025-ii-vroegmoderne-tijd-vraag8.png$$, $$De Portugese missionaris Diego del Santissimo Sacramento bezocht rond 1584 prehistorische rotstekeningen bij de Afrikaanse stad M''banza-Kongo. Hij schreef daarover: "Men denkt dat het Sint Thomas [een leerling van Jezus] was, die deze teksten in de steen achterliet." 2p 8 Leg uit dat Diego del Santissimo Sacramento de prehistorische Afrikaanse cultuur bekeek vanuit zijn eigen wereldbeeld.$$, array[]::uuid[]),
  ('6b636bbe-e3e3-495d-96a2-fa217ce908fd', 'c3aaa3f0-c76f-4c72-b0ee-e2905c240b1e', 10,
   '[{"domain": "Steden en burgers in de Lage Landen", "subdomain": "Burgerij in de Gouden Eeuw (1602-1700)"}]'::jsonb,
   '["bruikbaarheid", "rijke kooplieden", "status", "Gouden Eeuw", "schilderkunst", "bronverwijzing"]'::jsonb,
   $$Uitleggen waarom een familieportret van een Amsterdamse koopman bruikbaarder is voor onderzoek naar status dan naar dagelijks leven.$$,
   $$geschiedenis-vwo-2025-ii-vroegmoderne-tijd-vraag10.png$$, $$Gebruik bron 4. Stel: Je bestudeert de elite in de Republiek en je hebt twee onderzoeksonderwerpen:
1 Het benadrukken van status onder de rijke kooplieden.
2 Het dagelijks leven van rijke kooplieden. Je concludeert dat je de bron beter bruikbaar vindt voor je eerste onderzoeksonderwerp en minder bruikbaar voor je tweede onderzoeksonderwerp. 4p 10 Leg beide conclusies uit met een verwijzing naar de bron.$$, array['1b3d6682-04d5-40fd-9c6f-a1b93223428b']::uuid[]),
  ('9b592073-7bd1-4ae9-9f51-50afae0afe9c', '46480c9e-c3c4-45f0-aa14-33f6cbfab8f8', 16,
   '[{"domain": "China", "subdomain": "Verlies van regionale grootmacht (1842-1911)"}]'::jsonb,
   '["Kanton", "handelsposten", "opiumoorlogen", "ongelijke verdragen", "beeldvorming", "bronverwijzing"]'::jsonb,
   $$Aangeven welk beeld een schilderij uit 1806 geeft van de handel in Kanton en verklaren waarom die handelsposten na de opiumoorlogen minder belangrijk werden.$$,
   $$geschiedenis-vwo-2025-ii-china-1842-2001-vraag16.png$$, $$Gebruik bron 7. William Daniell maakt het schilderij na een rondreis door China. 3p 16 Licht de afbeelding toe door:
− aan te geven welk beeld Daniell weergeeft van de handel in Kanton, waarna je je antwoord ondersteunt met een verwijzing naar de bron, en
− zonder bron te verklaren dat de handelsposten in Kanton minder belangrijk worden na de Opiumoorlogen.$$, array['bfe2a46c-b540-4eed-bc8b-6e34f6311891']::uuid[]),
  ('07253331-b062-4971-b711-702708098114', '46480c9e-c3c4-45f0-aa14-33f6cbfab8f8', 18,
   '[{"domain": "China", "subdomain": "Ontstaan van de Volksrepubliek (1912-1949)"}]'::jsonb,
   '["Chiang Kaishek", "Sun Yat-sen", "Guomindang", "breuk nationalisten-communisten", "Noordelijke Veldtocht", "keerpunt"]'::jsonb,
   $$Uitleggen naar aanleiding van welk politiek keerpunt de weduwe van Sun Yat-sen Chiang Kaishek in 1927 van verraad beschuldigde.$$,
   $$geschiedenis-vwo-2025-ii-china-1842-2001-vraag18.png$$, $$In 1927 publiceerde de weduwe van Sun Yat-sen een pamflet waarin ze Chiang Kaishek ervan beschuldigde dat hij het politieke programma van Sun Yat-sen had verraden. Ze beweerde dat Chiang Kaishek geen sociale revolutie nastreefde, maar alleen een wisseling van de macht wilde. 2p 18 Leg uit naar aanleiding van welk politiek keerpunt in China de weduwe van Sun Yat-sen deze bewering deed.$$, array[]::uuid[]),
  ('3593c1ab-2b8f-48be-bfaa-571894493384', '46480c9e-c3c4-45f0-aa14-33f6cbfab8f8', 24,
   '[{"domain": "China", "subdomain": "Ontwikkeling tot grootmacht (1949-2001)"}]'::jsonb,
   '["Mao Zedong", "breuk met de Sovjet-Unie", "Culturele Revolutie", "Stalin", "buitenlandse politiek", "betrouwbaarheid"]'::jsonb,
   $$Uitleggen dat Mao's beeld van Stalin past bij de Chinese buitenlandse politiek en dat de lijfarts zijn dagboeken verbrandde door de Culturele Revolutie.$$,
   $$geschiedenis-vwo-2025-ii-china-1842-2001-vraag24.png$$, $$Gebruik bron 13. Twee gegevens:
1 Volgens historici geven de beschrijvingen van dr. Li Zhizui een betrouwbaar beeld van Mao en zijn ideeën.
2 Dr. Li Zhizui verbrandt zijn dagboeken in 1966, waarna hij ze in de jaren 1970 weer herschrijft. 4p 24 Leg uit:
− dat het beeld dat Mao volgens dr. Li Zhizui weergeeft van Stalin past bij de buitenlandse politiek van China in de jaren 1960, en
− dat dr. Li Zhizui besluit zijn dagboeken te verbranden vanwege de binnenlandse politiek in China in de jaren 1960.$$, array['61a261dc-9c55-46bd-b22e-c37db713b786']::uuid[]),
  ('1cfc7417-0112-48ba-9546-336e5d0d4cde', '46480c9e-c3c4-45f0-aa14-33f6cbfab8f8', 26,
   '[{"domain": "China", "subdomain": "Ontwikkeling tot grootmacht (1949-2001)"}]'::jsonb,
   '["WTO", "Verenigde Staten", "democratisering", "economische hervormingen", "Jiang Zemin", "handel"]'::jsonb,
   $$Uitleggen welke politieke verandering de VS in China wilden bevorderen met het WTO-lidmaatschap en hoe dat moest werken.$$,
   $$geschiedenis-vwo-2025-ii-china-1842-2001-vraag26.png$$, $$In 2000 maakte het Amerikaanse parlement het mogelijk dat China lid werd van de Wereldhandelsorganisatie (WTO). De Amerikaanse president zei: "Vandaag heeft het Huis van Afgevaardigden [deel van het parlement] een historische stap gezet (…) het zal nieuwe handelsdeuren openen voor Amerika en nieuwe hoop op verandering in China." 2p 26 Licht deze uitspraak toe door:
− de politieke verandering te noemen die de Verenigde Staten wilden bevorderen in China, en
− aan te geven hoe het lidmaatschap van de WTO deze verandering moest bevorderen.$$, array[]::uuid[]),
  ('58ccfa5c-1a5e-45fa-a282-529afe4991fc', '6e924cc7-bbc7-4bfc-bb0d-fc74ba6e7e9b', 17,
   '[{"domain": "Verlichting", "subdomain": "Verlichtingsideeën in de Europese politieke cultuur (1813-1900)"}]'::jsonb,
   '["sociale kwestie", "pauperisme", "armoede", "hogere burgerij", "eenzijdigheid", "kenmerkend aspect"]'::jsonb,
   $$Aantonen dat het beeld van de Groningse vereniging tegen het pauperisme over oorzaken van armoede eenzijdig is en dit verklaren.$$,
   $$geschiedenis-vwo-2025-ii-moderne-tijd-vraag17.png$$, $$Gebruik bron 8. Je concludeert dat de mening van het bestuur van de ''Algemeene Vereeniging tegen het Pauperisme'' over de oorzaken van armoede eenzijdig is. 4p 17 Ondersteun je conclusie door:
− uit te leggen met een verwijzing naar de bron dat het beeld dat het bestuur weergeeft over de oorzaken van armoede eenzijdig is, en
− deze eenzijdigheid te verklaren vanuit de positie van de bestuurders, en
− met een kenmerkend aspect uit die tijd aan te geven bij welk maatschappelijk thema het bestuur zich aansluit. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array['ed985eed-cf5f-41c8-a3ab-e8f581e537a3']::uuid[]),
  ('24ee16bc-0b1d-40e5-9caf-42fad82ffdb2', '6e924cc7-bbc7-4bfc-bb0d-fc74ba6e7e9b', 19,
   '[{"domain": "Duitsland in Europa", "subdomain": "Opkomst nationaalsocialisme en Tweede Wereldoorlog (1918-1945)"}]'::jsonb,
   '["economische crisis jaren '30", "emancipatie", "vrouwenarbeid", "bruikbaarheid", "Verenigde Staten", "kenmerkend aspect"]'::jsonb,
   $$Uitleggen waarom een foto van een vrouwendemonstratie in 1935 minder bruikbaar is voor emancipatie en welk kenmerkend aspect hij illustreert.$$,
   $$geschiedenis-vwo-2025-ii-moderne-tijd-vraag19.png$$, $$Gebruik bron 9. Stel: je selecteert deze foto voor een fotoboek over de Amerikaanse geschiedenis in de jaren 1930. 3p 19 Licht je selectie toe door:
− met een verwijzing naar de foto uit te leggen waardoor je deze foto minder bruikbaar vindt voor een hoofdstuk over de toenemende emancipatie van vrouwen, en
− voor een kenmerkend aspect uit die tijd aan te tonen dat je die kunt illustreren met deze foto. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array['9084e2f1-f1a4-4c3c-bbb1-0fc5f6d3d5c5']::uuid[]),
  ('34299ecd-36fa-4fe5-ab40-6eb5b557dbc2', '6e924cc7-bbc7-4bfc-bb0d-fc74ba6e7e9b', 27,
   '[{"domain": "Verlichting", "subdomain": "Verlichtingsideeën in de Europese politieke cultuur (1813-1900)"}, {"domain": "Duitsland in Europa", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["burgerlijk ideaal", "huishoudscholen", "emancipatie", "sociaal-culturele veranderingen", "rolpatronen", "kenmerkend aspect"]'::jsonb,
   $$Het negentiende-eeuwse burgerlijke ideaal achter huishoudscholen voor meisjes aantonen en de toelating van jongens in de jaren 1970 verklaren.$$,
   $$geschiedenis-vwo-2025-ii-moderne-tijd-vraag27.png$$, $$Twee gegevens:
1 Aan het eind van de negentiende eeuw richtten particulieren uit de hogere burgerij huishoudscholen op, speciaal voor meisjes uit de arbeidersklasse. Op het lesprogramma stonden vakken als koken, wassen, strijken en handwerken.
2 In de jaren 1970 mochten ook jongens zich aanmelden voor de huishoudscholen. 2p 27 Licht beide gegevens toe door:
− bij het eerste gegeven aan te tonen welk negentiende-eeuwse ideaal de hogere burgerij nastreefde met de huishoudscholen, en
− met behulp van een kenmerkend aspect het tweede gegeven te verklaren. Let op: je moet na het opschrijven van een kenmerkend aspect een uitleg geven.$$, array[]::uuid[]),
  ('d0022d95-d6dc-44da-bfb3-a70e5d84aabc', 'c7f7e673-274c-4cc6-9e2c-cab3430e6718', 20,
   '[{"domain": "Duitsland in Europa", "subdomain": "Opkomst nationaalsocialisme en Tweede Wereldoorlog (1918-1945)"}]'::jsonb,
   '["NSB", "Duitse bezetting van Nederland", "nazificatie", "stakingen 1943", "Mussert", "standplaatsgebondenheid"]'::jsonb,
   $$Uitleggen waarom NSB-districtsleider Stoetzer zich zorgen maakte over Duitse maatregelen en welke methode van nazificatie hij nastreefde.$$,
   $$geschiedenis-vwo-2025-ii-duitsland-in-europa-1918-1991-vraag20.png$$, $$Gebruik bron 10. Twee conclusies:
1 Stoetzer maakt zich zorgen over de maatregelen van de Duitse bezetter.
2 Stoetzer wil Nederland nazificeren. 3p 20 Ondersteun beide conclusies door:
− aan te geven waarom Stoetzer zich vanuit zijn positie zorgen maakt over de maatregelen van de Duitse bezetter, en
− uit te leggen welke methode van nazificatie Stoetzer nastreeft.$$, array['5d2f905d-c20e-48ff-b567-46fda9033f57']::uuid[]),
  ('4837f79b-f0a7-4f08-92c0-8ba1a37f74a7', 'c7f7e673-274c-4cc6-9e2c-cab3430e6718', 21,
   '[{"domain": "Duitsland in Europa", "subdomain": "Opkomst nationaalsocialisme en Tweede Wereldoorlog (1918-1945)"}]'::jsonb,
   '["betrouwbaarheid", "onderzoeksvraag", "Duitse bezetting van Nederland", "NSB", "stakingen 1943", "bruikbaarheid"]'::jsonb,
   $$Een onderzoeksvraag formuleren waarvoor het NSB-rapport over de stakingen van 1943 betrouwbare informatie bevat.$$,
   $$geschiedenis-vwo-2025-ii-duitsland-in-europa-1918-1991-vraag21.png$$, $$Gebruik bron 10 nog een keer. Stel: je wilt onderzoek doen naar de Duitse bezetting. 2p 21 Formuleer zelf een onderzoeksvraag over de Duitse bezetting waarvoor het rapport betrouwbare informatie bevat en geef aan waarom je de informatie in het rapport hiervoor betrouwbaar acht.$$, array['5d2f905d-c20e-48ff-b567-46fda9033f57']::uuid[]),
  ('5bb303d0-3875-4d36-8491-e15998aebfc6', 'c7f7e673-274c-4cc6-9e2c-cab3430e6718', 22,
   '[{"domain": "Duitsland in Europa", "subdomain": "Opkomst nationaalsocialisme en Tweede Wereldoorlog (1918-1945)"}, {"domain": "Duitsland in Europa", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["Ulbricht", "DDR", "communisme", "Tweede Wereldoorlog", "propaganda herkennen", "Sovjet-Unie"]'::jsonb,
   $$Uitleggen welke communistische visie Ulbricht in 1942 gaf op de oorlog en welke politieke visie hij in 1953 aan de DDR-bevolking wilde overbrengen.$$,
   $$geschiedenis-vwo-2025-ii-duitsland-in-europa-1918-1991-vraag22.png$$, $$Gebruik bron 11. Zowel met zijn oproep uit 1942 aan de Duitse troepen als met de publicatie hiervan in zijn boek in 1953 geeft Ulbricht een visie weer. 3p 22 Licht dit toe door:
− aan te geven welke communistische visie op de Tweede Wereldoorlog Ulbricht weergeeft in 1942, en
− uit te leggen met een verwijzing naar de bron welke politieke visie Ulbricht in 1953 wil overbrengen aan de bevolking van de DDR.$$, array['3150307d-56ac-4748-8003-e811ae23e53b']::uuid[]),
  ('fcc7c999-d647-49d7-a91b-d1d72bd8d443', 'c7f7e673-274c-4cc6-9e2c-cab3430e6718', 23,
   '[{"domain": "Duitsland in Europa", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["Comecon", "planeconomie", "DDR", "Ulbricht", "Chroesjtsjov", "Koude Oorlog"]'::jsonb,
   $$De kritiek van Ulbricht op de samenwerking binnen het Comecon in 1961 verklaren vanuit de planeconomie en de Koude Oorlog.$$,
   $$geschiedenis-vwo-2025-ii-duitsland-in-europa-1918-1991-vraag23.png$$, $$Gebruik bron 12. Ulbricht levert kritiek. 4p 23 Licht deze kritiek toe door:
− zonder bron aan te geven welk communistisch economisch beleid de DDR in navolging van de Sovjet-Unie invoert, en
− met bron aan te tonen dat de kritiek van Ulbricht is beïnvloed door de Koude Oorlog, en
− met bron uit te leggen waardoor Chroesjtsjov deze uitspraak van Ulbricht kan opvatten als kritiek op het beleid van de Sovjet-Unie.$$, array['ac9ac1c2-9c27-400d-bcf8-7ab5413f1679']::uuid[]),
  ('365d58f3-7655-4a3f-8610-7e4e3d4a72e1', 'c7f7e673-274c-4cc6-9e2c-cab3430e6718', 25,
