   '["Gorbatsjov", "perestrojka", "Brezjnevdoctrine", "Warschaupact", "einde Koude Oorlog", "DDR"]'::jsonb,
   $$Aangeven hoe de terugtrekking van Sovjettroepen in 1988 de perestrojka ondersteunde en welke beleidsmaatregel dit mogelijk maakte.$$,
   $$geschiedenis-vwo-2025-ii-duitsland-in-europa-1918-1991-vraag25.png$$, $$In 1988 besloot Gorbatsjov zes tankdivisies en 50.000 soldaten van het Sovjetleger terug te trekken uit de DDR, Tsjecho-Slowakije en Hongarije. 2p 25 Geef aan:
− op welke wijze deze beslissing het beleid van perestrojka ondersteunde, en
− door welke beleidsmaatregel van Gorbatsjov het terugtrekken van tanks en troepen mogelijk werd.$$, array[]::uuid[]);
